// ── Engine: parameter specs and number generation ──
function spec(s) {
  const fixed = s[0] === '=', int = s[0] === '#';
  const raw = s.replace(/^[=#]/, '');
  const mant = raw.toLowerCase().split('e')[0].replace('-', '').replace('.', '').replace(/^0+/, '');
  return { v: parseFloat(raw), fixed, int, sci: /e/i.test(raw), sf: Math.max(2, mant.length) };
}
function roundSf(x, sf) { return Number(x.toPrecision(sf)); }
function genParams(prob, original, rnd = Math.random) {
  for (let tries = 0; tries < 200; tries++) {
    const p = {};
    for (const [k, s] of Object.entries(prob.params)) {
      const sp = spec(s);
      if (original || sp.fixed) { p[k] = sp.v; continue; }
      const v = sp.v * (0.85 + rnd() * 0.3);
      p[k] = sp.int ? Math.max(1, Math.round(v)) : roundSf(v, sp.sf);
    }
    if (prob.derive) Object.assign(p, prob.derive(p));
    if (prob.valid && !prob.valid(p)) { if (original) break; continue; }
    const ans = prob.solve(p);
    if (Number.isFinite(ans) && ans > 0) return { p, ans };
    if (original) break;
  }
  const p = {};
  for (const [k, s] of Object.entries(prob.params)) p[k] = spec(s).v;
  if (prob.derive) Object.assign(p, prob.derive(p));
  return { p, ans: prob.solve(p) };
}

if (typeof module !== 'undefined') module.exports = { BANK, TOPICS, genParams, spec };
